describe('Change Password from Profile Settings', () => {
    beforeEach(() => {
        cy.visit('/profile/settings');
        cy.login('testuser', 'oldpassword'); // Assuming a custom command for login
    });

    it('should successfully change the password with valid inputs', () => {
        cy.get('input[name="currentPassword"]').type('oldpassword');
        cy.get('input[name="newPassword"]').type('newpassword123');
        cy.get('input[name="confirmPassword"]').type('newpassword123');
        cy.get('button[type="submit"]').click();

        cy.get('.notification').should('contain', 'Password changed successfully');
        cy.logout(); // Assuming a custom command for logout
        cy.login('testuser', 'newpassword123'); // Verify new password works
        cy.url().should('include', '/dashboard');
    });

    it('should show an error message when new passwords do not match', () => {
        cy.get('input[name="currentPassword"]').type('oldpassword');
        cy.get('input[name="newPassword"]').type('newpassword123');
        cy.get('input[name="confirmPassword"]').type('differentpassword');
        cy.get('button[type="submit"]').click();

        cy.get('.error-message').should('contain', 'Passwords do not match');
    });
});
